-- Versioned point contracts. Existing unknown/customer protocols remain unpublished drafts.
-- Historical rows and native addresses are retained; publication validates every explicit mapping.
alter table "wcs_protocol" add column "lifecycle_state" varchar(16) not null default 'draft';
alter table "wcs_protocol" add column "row_version" bigint not null default 0;
alter table "wcs_protocol" add column "published_revision_id" bigint;
alter table "wcs_protocol_point" add column "template_code" varchar(64) not null default 'unclassified';
alter table "wcs_protocol_point" add column "template_version" bigint not null default 1;
alter table "wcs_protocol_point" add column "operation" varchar(64) not null default 'control';
alter table "wcs_protocol_point" add column "direction" varchar(16) not null default 'request';
alter table "wcs_protocol_point" add column "point_scope" varchar(16) not null default 'internal';
alter table "wcs_protocol_point" add column "logical_type" varchar(64) not null default '';
alter table "wcs_protocol_point" add column "required" boolean not null default true;
alter table "wcs_protocol_point" add column "nullable" boolean not null default false;
alter table "wcs_protocol_point" add column "constraints" text not null default '{}';
alter table "wcs_protocol_point" add column "default_value" text default 'null';
alter table "wcs_protocol_point" add column "row_version" bigint not null default 0;
alter table "wcs_protocol_point" add column "active_identity" varchar(512);
create table "wcs_protocol_revision" (
 "id" bigint generated by default as identity primary key,
 "protocol_id" bigint not null,
 "revision" bigint not null,
 "protocol_type" varchar(64) not null,
 "fingerprint" varchar(64) not null,
 "points" text not null,
 "creator" varchar(512) not null default '',
 "create_time" timestamp(6) not null default current_timestamp,
 "last_update_time" timestamp(6) not null default current_timestamp,
 "is_valid" boolean not null default true,
 "tenant_id" bigint not null default 1
);
create unique index "uk_protocol_revision" on "wcs_protocol_revision" ("tenant_id", "protocol_id", "revision");

-- Only device profiles whose field semantics are present in the existing driver are classified.
update "wcs_protocol_point" set "template_code"='stacker'
where "protocol_id" in (select "id" from "wcs_protocol" where "protocol_code" in ('STACKER_STD','STACKER_OPCUA','PALLET_SIM_OPCUA'))
or "protocol_id" in (select a."protocol_id" from "wcs_application" a join "wcs_protocol" p on p."id"=a."protocol_id"
 where p."protocol_type"='sim' and a."device_type" in ('stacker','palletizer') and a."direction"='downstream');
update "wcs_protocol_point" set "template_code"='conveyor' where "protocol_id" in (select "id" from "wcs_protocol" where "protocol_code"='CONVEYOR_SIM');
update "wcs_protocol_point" set "template_code"='lift' where "protocol_id" in (select "id" from "wcs_protocol" where "protocol_code"='LIFT_SIM');
update "wcs_protocol_point" set "template_code"='auto_door' where "protocol_id" in (select "id" from "wcs_protocol" where "protocol_code"='DOOR_SIM');
update "wcs_protocol_point" set "direction"='response' where "template_code"<>'unclassified' and "point_group"='To_WCS';
update "wcs_protocol_point" set "point_scope"='business',"operation"='result'
 where "template_code"<>'unclassified' and "field_name" like 'status_%' and "direction"='response';
update "wcs_protocol_point" set "point_scope"='business',"operation"='dispatch' where "template_code"='stacker' and "direction"='request' and "field_name" in ('cmd_TaskType','cmd_TakeCoor_Row','cmd_TakeCoor_Column','cmd_TakeCoor_Floor','cmd_PutCoor_Row','cmd_PutCoor_Column','cmd_PutCoor_Floor','cmd_PortNum');
update "wcs_protocol_point" set "point_scope"='business',"operation"='dispatch' where "template_code"='conveyor' and "direction"='request' and "field_name" in ('cmd_DestStation');
update "wcs_protocol_point" set "point_scope"='business',"operation"='dispatch' where "template_code"='lift' and "direction"='request' and "field_name" in ('cmd_TargetFloor');
update "wcs_protocol_point" set "point_scope"='business',"operation"='dispatch' where "template_code"='auto_door' and "direction"='request' and "field_name" in ('cmd_Open','cmd_Close');
-- The simulator native node types are explicitly coordinated with Milo and SimAdapter.
-- Physical STACKER_STD/STACKER_OPCUA retain INT plus the conflicting 65534 range: publication rejects them.
update "wcs_protocol_point" set "data_type"='UINT' where "field_name" in ('cmd_TaskNum','status_TaskNum')
 and "protocol_id" in (select "id" from "wcs_protocol" where "protocol_code"='PALLET_SIM_OPCUA' or "protocol_type"='sim');
update "wcs_protocol_point" set "rw"='RW' where "field_name"='cmd_TaskNum' and "template_code"='stacker'
 and "protocol_id" in (select "id" from "wcs_protocol" where "protocol_code"='PALLET_SIM_OPCUA' or "protocol_type"='sim');
update "wcs_protocol_point" set "logical_type"='INT16' where "template_code"<>'unclassified' and "data_type"='INT';
update "wcs_protocol_point" set "logical_type"='UINT16' where "template_code"<>'unclassified' and "data_type"='UINT';
update "wcs_protocol_point" set "logical_type"='FLOAT32' where "template_code"<>'unclassified' and "data_type"='REAL';
update "wcs_protocol_point" set "logical_type"='ARRAY<INT16>',"constraints"='{"dimensions":[60],"length":60,"element_type":"INT16"}'
 where "template_code"='stacker' and "field_name"='status_ErrorCode' and "data_type"='ARRAY[1..60] OF INT';
update "wcs_protocol_point" set "constraints"='{"min":0,"max":1,"enum":[0,1]}' where "template_code"<>'unclassified' and "field_name" in ('WCS_Heart','PLC_Heart','cmd_Start','cmd_Go','cmd_Open','cmd_Close');
update "wcs_protocol_point" set "constraints"='{"min":1,"max":6,"enum":[1,2,3,4,5,6]}' where "template_code"<>'unclassified' and "field_name" in ('cmd_TaskType');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":2}' where "template_code"<>'unclassified' and "field_name" in ('cmd_TakeCoor_Row','cmd_PutCoor_Row');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":7}' where "template_code"<>'unclassified' and "field_name" in ('cmd_TakeCoor_Column','cmd_PutCoor_Column');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":9}' where "template_code"<>'unclassified' and "field_name" in ('cmd_TakeCoor_Floor','cmd_PutCoor_Floor');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":2}' where "template_code"<>'unclassified' and "field_name" in ('cmd_PortNum');
update "wcs_protocol_point" set "constraints"='{"min":1,"max":65534,"reserved_values":[0,65535]}' where "template_code"<>'unclassified' and "field_name" in ('cmd_TaskNum');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":65534}' where "template_code"<>'unclassified' and "field_name" in ('status_TaskNum');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":2,"enum":[0,1,2]}' where "template_code"<>'unclassified' and "field_name" in ('cmd_ConfirmTask');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":1,"enum":[0,1]}' where "template_code"<>'unclassified' and "field_name" in ('cmd_ResetFault');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":4,"enum":[0,1,2,3,4]}' where "template_code"<>'unclassified' and "field_name" in ('status_Mode');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":2,"enum":[0,1,2]}' where "template_code"<>'unclassified' and "field_name" in ('status_Task');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":6,"enum":[0,1,2,3,4,5,6]}' where "template_code"<>'unclassified' and "field_name" in ('status_TaskTypeFeedback');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":7}' where "template_code"<>'unclassified' and "field_name" in ('status_CurrentColumnNum');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":9}' where "template_code"<>'unclassified' and "field_name" in ('status_CurrentFloorNum');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":2,"enum":[0,1,2]}' where "template_code"<>'unclassified' and "field_name" in ('status_Cargo');
update "wcs_protocol_point" set "constraints"='{"min":1,"max":32767}' where "template_code"<>'unclassified' and "field_name" in ('cmd_DestStation','cmd_TargetFloor');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":32767}' where "template_code"<>'unclassified' and "field_name" in ('status_Position','status_CurrentFloor');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":1,"enum":[0,1]}' where "template_code"<>'unclassified' and "field_name" in ('status_Occupied');
update "wcs_protocol_point" set "constraints"='{"min":0,"max":3,"enum":[0,1,2,3]}' where "template_code"='auto_door' and "field_name"='status_DoorState';
update "wcs_protocol_point" set "constraints"='{"min":0,"max":1,"enum":[0,1]}' where "template_code"='lift' and "field_name"='status_DoorState';
update "wcs_protocol_point" set "constraints"='{"min":0,"max":32767}' where "template_code" in ('conveyor','lift','auto_door') and "field_name"='status_ErrorCode';
update "wcs_protocol_point" set "constraints"='{"unit":"mm/s"}' where "template_code"='stacker' and "field_name" in ('status_Speed_Lift','status_Speed_Walk','status_Speed_Fork');
update "wcs_protocol_point" set "constraints"='{"unit":"mm"}' where "template_code"='stacker' and "field_name" in ('status_CurrentPos_Lift','status_CurrentPos_Walk','status_CurrentPos_Fork');

-- Store complete HTTP point definitions at migration time. Runtime matching never synthesizes missing fields.
insert into "wcs_protocol" ("protocol_code","protocol_name","target_system","protocol_type","data_format","transport_template","version","status","lifecycle_state","remark","creator","tenant_id")
select 'HTTP_DEVICE_CONTRACT','HTTP设备点位协议','上位应用','http',
 '{"version":1,"point_container":"payload"}','{"transport":"http","roles":["upstream"]}','1','enabled','draft',
 '显式定义四种已实现设备的请求和响应点位，发布后才能建立关系','system', t."tenant_id"
from (select distinct "tenant_id" from "wcs_protocol" where "is_valid"=true) t
where not exists (select 1 from "wcs_protocol" x where x."protocol_code"='HTTP_DEVICE_CONTRACT' and x."tenant_id"=t."tenant_id");
insert into "wcs_protocol_point" ("protocol_id","point_group","field_name","symbol_name","address","data_type","rw","value_range","scale","sort","description","creator","tenant_id","template_code","template_version","operation","direction","point_scope","logical_type","required","nullable","constraints","default_value")
select http."id",pp."point_group",pp."field_name",pp."symbol_name",'payload.'||pp."field_name",
 case when pp."logical_type"='ARRAY<INT16>' then 'ARRAY[60] OF INT16' else pp."logical_type" end,
 pp."rw",pp."value_range",pp."scale",pp."sort",pp."description",'system',pp."tenant_id",
 pp."template_code",pp."template_version",pp."operation",pp."direction",pp."point_scope",pp."logical_type",pp."required",pp."nullable",pp."constraints",pp."default_value"
from "wcs_protocol_point" pp
join "wcs_protocol" source on source."id"=pp."protocol_id" and source."protocol_code" in ('PALLET_SIM_OPCUA','CONVEYOR_SIM','LIFT_SIM','DOOR_SIM')
join "wcs_protocol" http on http."protocol_code"='HTTP_DEVICE_CONTRACT' and http."tenant_id"=pp."tenant_id"
where pp."is_valid"=true and pp."point_scope"='business';
-- Duplicate/unknown identities are intentionally left null and unpublished for explicit remediation.
update "wcs_protocol_point" p set "active_identity"="template_code"||'/'||"template_version"||'/'||"operation"||'/'||"direction"||'/'||"field_name"
where p."is_valid"=true and p."template_code"<>'unclassified' and not exists (
 select 1 from "wcs_protocol_point" d where d."protocol_id"=p."protocol_id" and d."tenant_id"=p."tenant_id" and d."is_valid"=true and d."id"<>p."id"
 and d."template_code"=p."template_code" and d."template_version"=p."template_version" and d."operation"=p."operation" and d."direction"=p."direction" and d."field_name"=p."field_name"
);
create unique index "uk_protocol_point_identity" on "wcs_protocol_point" ("tenant_id","protocol_id","active_identity");
